CREATE TABLE rental_policies (id UNIQUEIDENTIFIER NOT NULL PRIMARY KEY DEFAULT NEWID(), deposit_percent DECIMAL(5,2) NOT NULL, cancellation_deadline_hours INT NOT NULL, created_at DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME(), updated_at DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME(), created_by NVARCHAR(100) NULL, updated_by NVARCHAR(100) NULL, version BIGINT NOT NULL DEFAULT 0);
CREATE TABLE fee_policies (id UNIQUEIDENTIFIER NOT NULL PRIMARY KEY DEFAULT NEWID(), name NVARCHAR(255) NOT NULL, fee_type NVARCHAR(30) NOT NULL, amount DECIMAL(19,2) NULL, percentage DECIMAL(5,2) NULL, active BIT NOT NULL DEFAULT 1, created_at DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME(), updated_at DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME(), created_by NVARCHAR(100) NULL, updated_by NVARCHAR(100) NULL, version BIGINT NOT NULL DEFAULT 0);
